import {formatSrt, passageRange} from './captions.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const categories=['Curiosity','Story','Mistake','Contrarian','Tutorial','Question','Before & after','Challenge'];
const state={hooks:[],videos:[],jobs:[],moments:[],presets:[],revision:null,exportLimit:24,momentSelection:new Set(),batchRequest:null,batchBusy:false,workspaceEditing:null,captionCues:[],transcription:null,passageStart:null,passageEnd:null,captionEditing:null,view:'library',category:'',favorites:false,selected:null,format:'vertical',editing:null,selectionPlaying:false,uploading:false,engineReady:false};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>`<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;
const bytes=n=>n>=1024**3?(n/1024**3).toFixed(1)+' GB':n>=1024**2?(n/1024**2).toFixed(1)+' MB':Math.round(n/1024)+' KB';
function clock(n){n=Math.max(0,Number(n)||0);const cs=Math.round(n*100),h=Math.floor(cs/360000),m=Math.floor(cs/6000)%60,s=Math.floor(cs/100)%60,c=cs%100;return (h?String(h).padStart(2,'0')+':':'')+String(m).padStart(2,'0')+':'+String(s).padStart(2,'0')+'.'+String(c).padStart(2,'0');}
function parseTime(text){const value=String(text).trim();if(!/^\d+(?::\d{1,2}){0,2}(?:\.\d{1,3})?$/.test(value))return NaN;const parts=value.split(':').map(Number);if(parts.length>1&&parts.slice(1).some(p=>p>=60))return NaN;return parts.reduce((sum,n)=>sum*60+n,0);}
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;$('#toasts').append(el);setTimeout(()=>el.remove(),error?7000:3600);}
async function api(url,method='GET',data){const response=await fetch(url,{method,headers:{'X-Hookcut':'1',...(data===undefined?{}:{'Content-Type':'application/json'})},body:data===undefined?undefined:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw new Error(result.error||'Something went wrong.');return result;}
function guard(fn){return async(...args)=>{try{await fn(...args);}catch(e){toast(e.message||'Something went wrong.',true);}};}
function draftKey(){return 'hookcut-draft-'+(state.selected||'new');}
function saveDraft(){try{localStorage.setItem(draftKey(),JSON.stringify({title:$('#clip-title').value,start:$('#start-time').value,end:$('#end-time').value,format:state.format,fit:$('#clip-fit').value,position:$('#crop-position').value,hook:$('#clip-hook').value,burn:$('#burn-hook').checked,quality:$('#clip-quality').value,mute:$('#mute-export').checked,includeSubtitles:$('#include-subtitles').checked,burnCaptions:$('#burn-captions').checked,subtitleOffset:$('#subtitle-offset').value}));}catch{}}
function readDraft(key){try{return JSON.parse(localStorage.getItem(key)||'null');}catch{return null;}}
function setView(view){if(!['library','studio','exports'].includes(view))view='library';if(state.view==='studio'&&view!=='studio'){$('#video').pause();state.selectionPlaying=false;saveDraft();}state.view=view;for(const el of $$('.view'))el.classList.toggle('hidden',el.id!=='view-'+view);for(const el of $$('.nav-link'))el.classList.toggle('active',el.dataset.view===view);$('#breadcrumb').textContent={library:'Hook library',studio:'Clip studio',exports:'Exports'}[view];if(location.hash!=='#'+view)history.replaceState(null,'','#'+view);if(view==='studio')requestAnimationFrame(updateFrame);}
function renderCategories(){$('#category-filters').innerHTML=['',...categories].map(c=>`<button class="category-chip ${state.category===c?'active':''}" data-category="${esc(c)}" aria-pressed="${state.category===c}">${c||'All hooks'}</button>`).join('');}
function renderHooks(){
  const search=$('#hook-search').value.toLowerCase().trim(),niche=$('#niche-filter').value,sort=$('#hook-sort').value;
  let hooks=state.hooks.filter(h=>(!state.category||h.category===state.category)&&(!state.favorites||h.favorite)&&(!niche||h.niche===niche)&&(!search||[h.text,h.notes,h.niche,...h.tags].join(' ').toLowerCase().includes(search)));
  if(sort==='used')hooks.sort((a,b)=>(b.uses||0)-(a.uses||0));else if(sort==='az')hooks.sort((a,b)=>a.text.localeCompare(b.text));else hooks.sort((a,b)=>b.createdAt.localeCompare(a.createdAt));
  $('#total-hooks').textContent=state.hooks.length;$('#nav-hook-count').textContent=state.hooks.length;$('#favorite-hooks').textContent=state.hooks.filter(h=>h.favorite).length;$('#own-hooks').textContent=state.hooks.filter(h=>!h.starter).length;
  $('#results-count').textContent=`${hooks.length} ${hooks.length===1?'hook':'hooks'}${search||niche||state.category||state.favorites?' matching your filters':''}`;
  $('#hooks-empty').classList.toggle('hidden',hooks.length>0);
  $('#hook-grid').innerHTML=hooks.map(h=>`<article class="hook-card" data-id="${esc(h.id)}"><div class="card-top"><span class="category-tag" data-category="${esc(h.category)}">${esc(h.category)}</span><button class="icon-button ${h.favorite?'favorited':''}" data-action="favorite" aria-label="${h.favorite?'Unfavorite':'Favorite'} hook" aria-pressed="${h.favorite}">${icon('star')}</button></div><p class="hook-text">${esc(h.text)}</p><div class="hook-meta"><span>${esc(h.niche)}</span>${h.tags.slice(0,2).map(t=>`<span>${esc(t)}</span>`).join('')}${h.uses?`<span>used ${h.uses}×</span>`:''}</div><div class="card-bottom"><button class="text-button use-hook" data-action="use">Use in clip ${icon('arrow')}</button><div class="card-actions"><button class="icon-button" data-action="copy" aria-label="Copy hook" title="Copy hook">${icon('copy')}</button><button class="icon-button" data-action="edit" aria-label="Edit hook and notes" title="Edit hook and notes">${icon('edit')}</button><button class="icon-button" data-action="delete" aria-label="Delete hook" title="Delete hook">${icon('trash')}</button></div></div></article>`).join('');
  const niches=[...new Set(state.hooks.map(h=>h.niche))].sort();$('#niche-filter').innerHTML='<option value="">All niches</option>'+niches.map(n=>`<option value="${esc(n)}">${esc(n)}</option>`).join('');if(niches.includes(niche))$('#niche-filter').value=niche;
}
function openHook(hook){state.editing=hook?.id||null;$('#save-hook-copy').classList.toggle('hidden',!hook);$('#hook-dialog-title').textContent=hook?'Make it yours':'Save a hook';$('#hook-text').value=hook?.text||'';$('#hook-category').value=hook?.category||'Curiosity';$('#hook-niche').value=hook?.niche||'';$('#hook-tags').value=hook?.tags.join(', ')||'';$('#hook-source').value=hook?.source||'';$('#hook-notes').value=hook?.notes||'';$('#hook-favorite').checked=hook?.favorite||false;$('#hook-character-count').textContent=$('#hook-text').value.length+' / 500';$('#hook-dialog').showModal();$('#hook-text').focus();}
function confirmAction(title,message){$('#confirm-title').textContent=title;$('#confirm-message').textContent=message;const d=$('#confirm-dialog');d.showModal();$('#confirm-no').focus();return new Promise(resolve=>{const cleanup=()=>{d.removeEventListener('close',close);$('#confirm-yes').onclick=null;$('#confirm-no').onclick=null;};const close=()=>{cleanup();resolve(false);};d.addEventListener('close',close);$('#confirm-yes').onclick=()=>{cleanup();d.close();resolve(true);};$('#confirm-no').onclick=()=>d.close();});}
function renderSources(){$('#source-count').textContent=state.videos.length;$('#source-list').innerHTML=state.videos.map(v=>`<div class="source-item ${state.selected===v.id?'selected':''}" data-id="${v.id}"><button class="source-select" data-source="${v.id}" title="${esc(v.name)}"><strong>${esc(v.name)}</strong><small>${clock(v.duration)} · ${bytes(v.bytes)}</small></button><button class="icon-button" data-remove-source="${v.id}" aria-label="Remove ${esc(v.name)}">${icon('trash')}</button></div>`).join('');}
function selectedVideo(){return state.videos.find(v=>v.id===state.selected);}
function renderCaptions(){const v=selectedVideo();$('#import-subtitles').disabled=!v;$('#subtitle-info').textContent=v?.subtitleCount?`${v.subtitleName} · ${v.subtitleCount} cues`:'No captions attached.';$('#subtitle-controls').classList.toggle('hidden',!v?.subtitleCount);updateCaptionOverlay();renderTranscript();renderTranscriptionStatus();}
async function loadCaptions(id){state.captionCues=[];state.passageStart=null;state.passageEnd=null;renderCaptions();const result=await api('/api/videos/'+id+'/subtitles');if(state.selected===id){state.captionCues=result.cues;renderCaptions();}}
function updateCaptionOverlay(){const offset=Number($('#subtitle-offset').value)||0,time=$('#video').currentTime-offset;const cues=state.captionCues.filter(c=>c.start<=time&&c.end>time);const html=($('#include-subtitles').checked||$('#burn-captions').checked)&&cues.length?'<span>'+esc(cues.map(c=>c.text).join('\n'))+'</span>':'';if($('#caption-overlay').innerHTML!==html)$('#caption-overlay').innerHTML=html;}
function selectVideo(id,carryHook=false){
  if(state.selected)saveDraft();const v=state.videos.find(v=>v.id===id);if(!v)return;const carried=$('#clip-hook').value;state.selected=id;state.selectionPlaying=false;state.momentSelection.clear();state.batchRequest=null;renderMoments();
  const draft=readDraft(draftKey());$('#video').src=v.url;$('#preview-empty').classList.add('hidden');$('#video-frame').classList.remove('hidden');$('#preview-error').classList.add('hidden');$('#scrubber').max=v.duration;$('#scrubber').value=0;$('#scrubber').disabled=false;$('#play-toggle').disabled=false;$('#mute-preview').disabled=false;$('#video-duration').textContent=clock(v.duration);$('#playhead').textContent=clock(0);
  $('#clip-title').value=draft?.title||v.name.replace(/\.[^.]+$/,'')+' — clip';$('#start-time').value=draft?.start||clock(0);$('#end-time').value=draft?.end||clock(Math.min(v.duration,30));state.format=draft?.format||'vertical';$('#clip-fit').value=draft?.fit||'cover';$('#crop-position').value=draft?.position??50;$('#clip-hook').value=carryHook&&carried?carried:(draft?.hook||'');$('#burn-hook').checked=!!draft?.burn;$('#clip-quality').value=draft?.quality||'720';$('#mute-export').checked=!!draft?.mute;$('#include-subtitles').checked=draft?.includeSubtitles!==false;$('#burn-captions').checked=!!draft?.burnCaptions;$('#subtitle-offset').value=draft?.subtitleOffset||0;void loadCaptions(id).catch(e=>toast(e.message,true));renderSources();updateFrame();updateTrim();try{localStorage.setItem('hookcut-last-video',id);}catch{}
}
function updateFrame(){const v=selectedVideo(),format=state.format;const ratio=format==='vertical'?9/16:format==='square'?1:format==='landscape'?16/9:v?v.width/v.height:16/9;const stage=$('#preview-area');const maxH=stage.clientHeight-34,maxW=stage.clientWidth-34;const h=Math.min(maxH,maxW/ratio),w=h*ratio;const frame=$('#video-frame');frame.style.height=h+'px';frame.style.width=w+'px';frame.style.aspectRatio=String(ratio);$('#video').style.objectFit=format==='original'?'contain':$('#clip-fit').value;$('#video').style.objectPosition=$('#crop-position').value+'% '+$('#crop-position').value+'%';$('#position-value').value=$('#crop-position').value+'%';$('#position-field').classList.toggle('hidden',$('#clip-fit').value==='contain'||format==='original');$('#clip-fit').disabled=format==='original';$('#preview-format').textContent={vertical:'9:16',square:'1:1',landscape:'16:9',original:'Original'}[format];for(const b of $$('[data-format]')){b.classList.toggle('active',b.dataset.format===format);b.setAttribute('aria-pressed',String(b.dataset.format===format));}$('#safe-guides').classList.toggle('hidden',!$('#show-guides').checked);$('#hook-overlay').style.fontSize=(w*.046)+'px';$('#caption-overlay').style.fontSize=(w*.04)+'px';updateHookOverlay();updateCaptionOverlay();}
function wrapHook(text){const lines=[];let line='';for(const word of text.replace(/\s+/g,' ').trim().split(' ')){for(const chunk of word.match(/.{1,34}/gu)||[]){if(line&&(line+' '+chunk).length>34){lines.push(line);line='';}line+=(line?' ':'')+chunk;}}if(line)lines.push(line);return lines.slice(0,5).join('\n');}
function updateHookOverlay(){const start=parseTime($('#start-time').value),relative=$('#video').currentTime-start;const visible=$('#burn-hook').checked&&$('#clip-hook').value.trim()&&relative>=-.05&&relative<3;$('#hook-overlay').innerHTML=visible?'<span>'+esc(wrapHook($('#clip-hook').value))+'</span>':'';}
function clipValues(){return {videoId:state.selected,title:$('#clip-title').value.trim(),start:parseTime($('#start-time').value),end:parseTime($('#end-time').value),format:state.format,fit:$('#clip-fit').value,position:Number($('#crop-position').value),quality:$('#clip-quality').value,hookText:$('#clip-hook').value.trim(),burnHook:$('#burn-hook').checked,mute:$('#mute-export').checked,includeSubtitles:$('#include-subtitles').checked,burnCaptions:$('#burn-captions').checked,subtitleOffset:Number($('#subtitle-offset').value)};}
function validation(){const v=selectedVideo();if(!v)return 'Import a video to get started.';if(!state.engineReady)return 'The video engine is unavailable.';const c=clipValues();if(!Number.isFinite(c.subtitleOffset)||Math.abs(c.subtitleOffset)>3600)return 'Caption offset must be between -3600 and 3600 seconds.';if(!Number.isFinite(c.start)||!Number.isFinite(c.end))return 'Use seconds or a timestamp such as 01:24.50.';if(c.start<0||c.end>v.duration+.05||c.end-c.start<.2)return 'Set a start and end within the video, at least 0.2 seconds apart.';return '';}
function updateTrim(){const v=selectedVideo(),c=clipValues(),valid=Number.isFinite(c.start)&&Number.isFinite(c.end)&&v;$('#selection-duration').textContent=valid?Math.max(0,c.end-c.start).toFixed(2)+'s selected':'0.00s selected';$('#trim-selection').style.left=(valid?Math.max(0,Math.min(100,c.start/v.duration*100)):0)+'%';$('#trim-selection').style.width=(valid?Math.max(0,Math.min(100,(c.end-c.start)/v.duration*100)):0)+'%';const error=validation();$('#export-validation').textContent=error||'H.264 MP4 · saved locally · original unchanged';$('#export-clip').disabled=!!error;$('#preview-selection').disabled=!!error;$('#save-moment').disabled=!!error;$('#bookmark-moment').disabled=!v;$('#set-start').disabled=!v;$('#set-end').disabled=!v;for(const [id,value] of [['start-handle',c.start],['end-handle',c.end]]){$('#'+id).disabled=!v;$('#'+id).max=v?.duration||100;$('#'+id).value=Number.isFinite(value)?value:0;}$('#import-subtitles').disabled=!v;updateHookOverlay();updateCaptionOverlay();}
function jobCard(j){const busy=['queued','running'].includes(j.status);const labels={queued:'In queue',running:'Exporting',done:'Ready',failed:'Needs attention',cancelled:'Cancelled'};return `<article class="job-card" data-id="${j.id}"><div class="job-top"><span class="job-status ${j.status}">${labels[j.status]||j.status}${j.status==='running'?' · '+j.progress+'%':''}</span><span class="small-eyebrow">${esc(j.format)} · ${j.quality}p</span></div><h3>${esc(j.title)}</h3><p>${clock(j.start)} → ${clock(j.end)} · ${(j.end-j.start).toFixed(2)}s${j.bytes?' · '+bytes(j.bytes):''}</p><p title="${esc(j.sourceName)}">${esc(j.sourceName)}</p>${j.hookText?`<p class="job-hook">${esc(j.hookText.slice(0,150))}${j.hookText.length>150?'…':''}</p>`:''}${busy?`<progress max="100" value="${j.progress}" aria-label="Export progress"></progress>`:''}${j.error?`<p>${esc(j.error)}</p>`:''}<div class="job-actions">${j.status==='done'?`<a class="button" href="${j.url}?download">${icon('download')}Download</a><button class="text-button" data-job-action="preview">Preview</button>${j.hookText?'<button class="text-button" data-job-action="hook">Hook .txt</button>':''}${j.subtitleCount?`<a class="text-button" href="/exports/${j.id}/subtitles">Captions .srt</a>`:''}`:busy?'<button class="text-button" data-job-action="cancel">Cancel export</button>':'<button class="button" data-job-action="retry">Retry export</button>'}${!busy&&state.videos.some(v=>v.id===j.videoId)?'<button class="text-button" data-job-action="edit-copy">Edit a copy</button>':''}${!busy?`<button class="icon-button" data-job-action="delete" aria-label="Delete export">${icon('trash')}</button>`:''}</div></article>`;}
function renderJobs(){const jobs=state.jobs;$('#nav-export-count').textContent=jobs.filter(j=>j.status==='done').length;const empty='<div class="empty-state">'+icon('cut')+'<h2>A little empty. A lot of possibility.</h2><p>Your exported clips will appear here. Start with a moment in the studio.</p></div>';const query=$('#export-search').value.trim().toLowerCase(),status=$('#export-status').value;const matching=jobs.filter(j=>(!query||[j.title,j.hookText,j.sourceName].join(' ').toLowerCase().includes(query))&&(status==='all'||(status==='active'?['running','queued'].includes(j.status):j.status===status)));$('#all-jobs').innerHTML=matching.length?matching.slice(0,state.exportLimit).map(jobCard).join(''):jobs.length?'<p class="moment-empty">No exports match your search or status filter.</p>':empty;$('#export-results').textContent=`${Math.min(state.exportLimit,matching.length)} of ${matching.length} clips`;$('#more-exports').classList.toggle('hidden',matching.length<=state.exportLimit);$('#studio-jobs').innerHTML=jobs.length?jobs.slice(0,3).map(jobCard).join(''):empty;$('#export-stats').innerHTML=`<span><strong>${jobs.filter(j=>j.status==='done').length}</strong> ready to download</span><span><strong>${jobs.filter(j=>['queued','running'].includes(j.status)).length}</strong> in progress</span><span><strong>${bytes(jobs.filter(j=>j.status==='done').reduce((sum,j)=>sum+(j.bytes||0),0))}</strong> exported</span>`;}
async function refresh(){const data=await api('/api/state');const old=selectedVideo();Object.assign(state,{hooks:data.hooks,videos:data.videos,jobs:data.jobs,moments:data.moments,presets:data.presets,revision:data.revision,engineReady:data.engineReady,transcription:data.transcription,captionBurnReady:data.captionBurnReady});renderTranscriptionStatus();$('#engine-warning').classList.toggle('hidden',state.engineReady);renderHooks();renderSources();renderJobs();renderPresets();renderMoments();updateTrim();const current=selectedVideo();if(current&&current.subtitleRevision!==old?.subtitleRevision)await loadCaptions(current.id);}

function importVideo(file){if(state.uploading)return toast('A video is already importing.');if(!file)return;if(!/\.(mp4|mov|mkv|webm|m4v|avi)$/i.test(file.name))return toast('Choose a supported video file.',true);if(file.size>2*1024**3)return toast('Choose a video smaller than 2 GB.',true);state.uploading=true;$('#upload-status').classList.remove('hidden');$('#upload-text').textContent='Copying video…';$('#upload-progress').value=0;$('#import-video').disabled=true;const xhr=new XMLHttpRequest();xhr.open('POST','/api/videos');xhr.setRequestHeader('X-Hookcut','1');xhr.setRequestHeader('X-File-Name',encodeURIComponent(file.name));xhr.setRequestHeader('Content-Type','application/octet-stream');xhr.upload.onprogress=e=>{if(e.lengthComputable){$('#upload-progress').value=e.loaded/e.total*100;$('#upload-text').textContent=e.loaded===e.total?'Reading video…':`Importing ${Math.round(e.loaded/e.total*100)}%`;}};xhr.onload=()=>{try{const data=JSON.parse(xhr.responseText);if(xhr.status>=400)throw new Error(data.error||'Import failed.');state.videos.unshift(data);selectVideo(data.id,true);toast('Video imported. Find your first moment.');}catch(e){toast(e.message,true);}finally{finish();}};xhr.onerror=()=>{toast('The import was interrupted. Check that the app is still running.',true);finish();};function finish(){state.uploading=false;$('#upload-status').classList.add('hidden');$('#import-video').disabled=false;$('#video-input').value='';}xhr.send(file);}
function mark(which){if(!selectedVideo())return;$('#'+which+'-time').value=clock($('#video').currentTime);state.selectionPlaying=false;updateTrim();saveDraft();}
async function togglePlay(){const v=$('#video');state.selectionPlaying=false;if(v.paused)await v.play();else v.pause();}
function downloadText(text,name,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}

function renderTranscriptionStatus(){
  const t=state.transcription,v=selectedVideo(),job=t?.jobs.find(j=>j.videoId===v?.id),busy=job?.status==='running',anyBusy=t?.jobs.some(j=>j.status==='running');
  $('#setup-transcription').classList.toggle('hidden',!t?.supported||t.model.status==='ready');
  $('#setup-transcription').disabled=t?.model.status==='downloading';
  $('#setup-transcription').textContent=t?.model.status==='downloading'?`Downloading model · ${t.model.progress}%`:'Download speech model · 78 MB';
  $('#generate-transcript').disabled=!v?.hasAudio||t?.model.status!=='ready'||anyBusy;
  $('#generate-transcript').textContent=v?.subtitleCount?'Regenerate transcript':'Generate transcript';
  $('#cancel-transcript').classList.toggle('hidden',!busy);
  $('#transcript-language').disabled=!!anyBusy;
  $('#import-subtitles').disabled=!v||busy;$('#remove-subtitles').disabled=!!busy;
  $('#burn-captions').disabled=state.captionBurnReady===false;
  let message=!t?.supported?'Automatic transcription needs an FFmpeg build with the whisper filter. You can still import an SRT.':t.model.status==='downloading'?`Downloading and verifying the speech model · ${t.model.progress}%`:t.model.status==='failed'?t.model.error:t.model.status!=='ready'?'Download the speech model once. No account, API key, or footage upload.':!v?'Import a video to generate a transcript.':!v.hasAudio?'This source has no audio track. Import SRT captions instead.':busy?`Generating transcript · ${job.progress}% · you can keep preparing clips`:job?.status==='failed'?job.error:job?.status==='cancelled'?'Transcription cancelled. Existing captions are preserved.':job?.status==='done'?'Transcript ready. Review the words before exporting.':'Ready to transcribe on this computer.';
  $('#transcription-status').textContent=message;
  const progress=$('#transcription-progress');progress.classList.toggle('hidden',!busy&&t?.model.status!=='downloading');progress.value=busy?job.progress:t?.model.progress||0;
}
let transcriptLimit=100;
function chosenPassage(){return passageRange(state.captionCues,state.passageStart,state.passageEnd,selectedVideo()?.duration||0,Number($('#subtitle-offset').value)||0);}
function renderPassage(){const range=chosenPassage();$('#use-passage').disabled=!range;$('#passage-info').textContent=range?`${range.count} ${range.count===1?'line':'lines'} · ${clock(range.start)} → ${clock(range.end)} · ${(range.end-range.start).toFixed(2)}s`:'Click a line to preview. Use Start here and End here to select a passage.';}
function renderTranscript(){
  const query=$('#transcript-search').value.trim().toLowerCase(),rows=state.captionCues.map((cue,index)=>({cue,index})).filter(({cue})=>!query||cue.text.toLowerCase().includes(query));
  const first=Math.min(state.passageStart??-1,state.passageEnd??-1),last=Math.max(state.passageStart??-1,state.passageEnd??-1);
  $('#transcript-list').innerHTML=rows.length?rows.slice(0,transcriptLimit).map(({cue,index})=>`<article class="transcript-row ${index>=first&&index<=last?'selected':''}"><button class="transcript-cue" data-cue="${index}" title="Preview this line"><time>${clock(Math.max(0,cue.start+(Number($('#subtitle-offset').value)||0)))}</time><span>${esc(cue.text)}</span></button><div class="transcript-row-actions"><button class="text-button" data-passage-start="${index}" aria-label="Start passage at line ${index+1}">Start here</button><button class="text-button" data-passage-end="${index}" aria-label="End passage at line ${index+1}">End here</button><button class="text-button" data-caption-edit="${index}" aria-label="Edit caption ${index+1}">Edit</button></div></article>`).join('')+(rows.length>transcriptLimit?`<button class="button" id="more-transcript">Show more lines (${rows.length-transcriptLimit} remaining)</button>`:''):`<p class="transcript-empty">${query?'No matching phrases. Try another search.':'Generate a transcript or import an SRT to find your next clip.'}</p>`;
  $('#download-transcript').disabled=!state.captionCues.length;renderPassage();
}
$('#setup-transcription').onclick=guard(async()=>{const t=await api('/api/transcription/model','POST');state.transcription=t;renderTranscriptionStatus();});
