$('#import-subtitles').onclick=()=>$('#subtitle-input').click();
$('#subtitle-input').onchange=guard(async e=>{const file=e.target.files[0],id=state.selected;if(!file||!id)return;try{if(file.size>1024**2)throw new Error('Choose an SRT file smaller than 1 MB.');const result=await api('/api/videos/'+id+'/subtitles','POST',{name:file.name,text:await file.text()});const v=state.videos.find(v=>v.id===id);if(v){v.subtitleName=result.name;v.subtitleCount=result.cues.length;}if(state.selected===id){state.captionCues=result.cues;$('#include-subtitles').checked=true;$('#subtitle-offset').value=0;renderCaptions();saveDraft();}toast(`${result.cues.length} subtitle cues imported.`);}finally{e.target.value='';}});
$('#remove-subtitles').onclick=guard(async()=>{const id=state.selected;if(!id)return;if(!await confirmAction('Remove these captions?','This detaches the imported captions from this source. Already exported subtitle files stay unchanged.'))return;await api('/api/videos/'+id+'/subtitles','DELETE');const v=state.videos.find(v=>v.id===id);if(v){delete v.subtitleName;delete v.subtitleCount;}if(state.selected===id){state.captionCues=[];renderCaptions();}toast('Captions removed from this source.');});
document.addEventListener('keydown',guard(async e=>{if(document.querySelector('dialog[open]')||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable||e.ctrlKey||e.metaKey||e.altKey)return;if(e.key===' '&&e.target.closest('button,a'))return;if(e.key==='/'&&state.view==='library'){e.preventDefault();$('#hook-search').focus();}if(state.view!=='studio'||!selectedVideo())return;const key=e.key.toLowerCase();if(key===' '){e.preventDefault();await togglePlay();}if(key==='i')mark('start');if(key==='o')mark('end');if(['arrowleft','arrowright'].includes(key)){e.preventDefault();state.selectionPlaying=false;$('#video').currentTime=Math.max(0,Math.min(selectedVideo().duration,$('#video').currentTime+(key==='arrowright'?1:-1)*(e.shiftKey?5:1)));}}));
window.addEventListener('resize',updateFrame);window.addEventListener('hashchange',()=>setView(location.hash.slice(1)));window.addEventListener('beforeunload',saveDraft);
let pollFailures=0,pollBusy=false;
async function pollActivity(){if(pollBusy||document.hidden)return;pollBusy=true;try{const data=await api('/api/activity');state.transcription=data.transcription;renderTranscriptionStatus();if(data.revision!==state.revision){const oldJobs=state.jobs;await refresh();for(const j of state.jobs)if(j.status==='done'&&oldJobs.some(old=>old.id===j.id&&['queued','running'].includes(old.status)))toast(`“${j.title}” is ready.`);}else{for(const progress of data.progress){const job=state.jobs.find(j=>j.id===progress.id);if(job)job.progress=progress.progress;for(const card of $$('.job-card'))if(card.dataset.id===progress.id){const bar=card.querySelector('progress');if(bar)bar.value=progress.progress;const label=card.querySelector('.job-status');if(label)label.textContent='Exporting · '+progress.progress+'%';}}}if(pollFailures>0)toast('Reconnected to your local workspace.');pollFailures=0;}catch{pollFailures++;if(pollFailures===2)toast('Connection lost. Keep the Hookcut launcher running.',true);}finally{pollBusy=false;}}
setInterval(pollActivity,2000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)void pollActivity();});

try{await refresh();const initial=location.hash.slice(1)||'library';let last;try{last=localStorage.getItem('hookcut-last-video');}catch{}if(state.videos.length)selectVideo(state.videos.some(v=>v.id===last)?last:state.videos[0].id);else{const draft=readDraft(draftKey());if(draft?.hook)$('#clip-hook').value=draft.hook;}setView(initial);}catch(e){toast('Could not load your workspace: '+e.message,true);}
